package com.cloudticket.activity.api;
import com.cloudticket.activity.service.ActivityCatalog; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/activities") public class ActivityAdminController { private final ActivityCatalog catalog; public ActivityAdminController(ActivityCatalog catalog){this.catalog=catalog;} private void allowed(@RequestHeader(value="X-User-Permissions",defaultValue="") String p){if(!p.contains("activity:write")&&!p.contains("activity:publish"))throw new SecurityException("forbidden");} @PostMapping public ActivityCatalog.Activity create(@RequestBody Map<String,String> body,@RequestHeader(value="X-User-Permissions",defaultValue="") String p){allowed(p);return catalog.create(body.get("title"),body.get("organizer"));} @PostMapping("/{id}/publish") public ActivityCatalog.Activity publish(@PathVariable String id,@RequestHeader(value="X-User-Permissions",defaultValue="") String p){allowed(p);return catalog.publish(id);} @PostMapping("/{id}/layout/freeze") public ActivityCatalog.Activity freeze(@PathVariable String id,@RequestHeader(value="X-User-Permissions",defaultValue="") String p){allowed(p);return catalog.freezeLayout(id);} }
